const TOTAL = 100;      // functions defined on load
const CALLED = 20;      // functions actually called at startup
const PREPARSE = 1;     // cost to skim one body
const FULLPARSE = 2;    // cost to full-parse one body

// Lazy: every body is pre-parsed; only called bodies are also full-parsed.
const lazy = TOTAL * PREPARSE + CALLED * FULLPARSE;

// Eager: every body is full-parsed once up front, no pre-parse skim.
const eager = TOTAL * FULLPARSE;

console.log('lazy=' + lazy + ' eager=' + eager + ' winner=' + (lazy < eager ? 'lazy' : 'eager'));

